 let chars=clusters(status),line=0;while(chars.length){labels.push({id:'status_'+line,text:chars.splice(0,22).join(''),x:labelX,y:45+line*20,font_size:16,color:'#ffffff'});line++;}
 labels.push({id:'goal',text:t('goal'),x:12,y:425,font_size:18,color:'#ffffff'});
